<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class MatchSquadPlayer extends Model { protected $fillable=['match_squad_id','player_id','selection_status','override_used','override_reason']; protected $casts=['override_used'=>'boolean']; public function matchSquad():BelongsTo{return $this->belongsTo(MatchSquad::class);} public function player():BelongsTo{return $this->belongsTo(Player::class);} }